import {materialInventory,filterMaterials,materialParameterInventory,materialSubjects,resolveMaterialSelection,cleanMaterialSelection,materialSelectionAudit} from './material-selection.js';
import {parameterNameKey} from './parameter-index.js';
import {strictNumber} from './measurements.js';
export function createMaterialPicker(config){
 const esc=config.escape,$=selector=>document.querySelector(selector);let state=cleanMaterialSelection(),saved=cleanMaterialSelection(),revision=0,savedRevision=0,saving=null,error='',timer,inputTimer,limit=100,showSelected=false,nextTab='table',preferred=null;
 const all=()=>materialInventory(config.getPapers()),resolved=()=>resolveMaterialSelection(config.getPapers(),state.keys),subjects=()=>materialSubjects(resolved().selected),supported=()=>config.canPersist?.()!==false;
 function status(){const r=resolved();document.querySelectorAll('[data-material-mode-summary]').forEach(node=>node.textContent=state.mode==='material'?r.selected.length+' 项材料 / 样品 · '+r.papers+' 篇来源':'保留原有文献选择；也可直接细选材料和样品');document.querySelectorAll('[data-material-save-status]').forEach(node=>{node.textContent=error?'选择未保存：'+error:saving?'正在保存选择…':revision!==savedRevision?'选择待保存':'';node.classList.toggle('is-error',Boolean(error));});document.querySelectorAll('[data-material-retry],[data-material-discard]').forEach(button=>button.hidden=!error);}
 async function flush(){clearTimeout(inputTimer);const input=$('#material-query');if(input&&input.value!==state.filters.query&&supported()){state={...state,filters:{...state.filters,query:input.value}};revision++;}clearTimeout(timer);if(saving)return saving.then(()=>revision!==savedRevision?flush():undefined);if(revision===savedRevision)return;const ticket=revision,payload=cleanMaterialSelection(state);saving=Promise.resolve().then(()=>config.persist(payload));status();try{await saving;savedRevision=ticket;saved=payload;error='';}catch(e){error=e.message;throw e;}finally{saving=null;status();}if(revision!==savedRevision)return flush();}
 function change(next,{delay=false}={}){if(!supported()){config.toast('请重新启动 Materia 后使用按材料选择，当前桌面接口尚未更新。');return false;}const oldMode=state.mode;state=cleanMaterialSelection(next);if(oldMode!=='material'&&state.mode==='material')config.onMaterialMode?.();revision++;error='';clearTimeout(timer);timer=setTimeout(()=>flush().catch(()=>{}),delay?350:0);config.changed?.();status();return true;}
 function load(value){if(saving||revision!==savedRevision)throw Error('请先保存当前的材料选择。');try{state=cleanMaterialSelection(value);}catch(e){state=cleanMaterialSelection();config.toast('材料选择设置暂无法识别，已保留原设置并按文献打开：'+e.message,true);}saved=cleanMaterialSelection(state);revision=savedRevision=0;error='';limit=100;showSelected=false;config.changed?.();}
 function modeBar(){const r=resolved();return `<div class="comparison-mode-bar"><div class="comparison-mode-switch" role="group" aria-label="性能对比选择方式"><button type="button" data-material-mode="paper" aria-pressed="${state.mode==='paper'}">按文献</button><button type="button" data-material-mode="material" aria-pressed="${state.mode==='material'}">按材料</button></div><span class="comparison-mode-hint" data-material-mode-summary>${state.mode==='material'?`${r.selected.length} 项材料 / 样品 · ${r.papers} 篇来源`:'保留原有文献选择；也可直接细选材料和样品'}</span><span data-material-save-status role="status"></span><button type="button" data-material-retry hidden>重试保存</button><button type="button" data-material-discard hidden>还原已保存选择</button></div>`;}
 async function setMode(mode){if(state.mode===mode)return true;clearTimeout(inputTimer);const input=$('#material-query');if(!change({...state,mode,filters:{...state.filters,query:input?.value??state.filters.query}}))return false;return true;}
 function selectionHTML(){const r=resolved();return `${missingHTML(r)}<details class="figure-paper-selection"><summary>已选 ${r.selected.length} 项材料 / 样品 · ${r.materials} 个材料 · ${r.papers} 篇来源文献</summary><div class="material-selected-list">${r.selected.map(row=>`<div><strong>${esc(row.materialName)}</strong><small>${esc([row.sample||'样品未填',row.conditions||'条件未填'].join(' · '))}</small><span>来源文献：<button data-material-open-paper="${esc(row.paperId)}">${esc(row.paper.title)}</button></span><button data-material-remove="${esc(row.key)}" aria-label="移除材料选择 ${esc(row.materialName)}">×</button></div>`).join('')}</div><button class="outline-button" data-material-action="pick">调整 / 补选材料</button></details>`;}
 function missingHTML(r){return r.missing.length?`<div class="material-missing" role="status">${r.missing.length} 项原材料、样品或条件已删除 / 变更，未自动匹配到其他数据。<button type="button" data-material-action="remove-missing">移除失效选择</button></div>`:'';}
 function recordHTML(row){
  const selectedParameter=parameterNameKey(state.filters.parameter),records=row.measurements.filter(m=>!selectedParameter||parameterNameKey(m.name)===selectedParameter&&(state.filters.unit==='*'||String(m.unit||'').normalize('NFKC').trim()===state.filters.unit)),render=m=>{let valid=true;try{strictNumber(m.value);}catch{valid=false;}return `<span class="material-parameter-record ${valid?'':'is-invalid'}"><b>${esc(m.name)}</b> ${m.value===''||m.value==null?'数值未填':esc(m.qualifier||'')+esc(m.value)} ${esc(m.unit||'单位未填')}${!valid?' · 数值待核对':''}${m.source?`<small>数据位置：${esc(m.source)}</small>`:''}</span>`;};
  return records.length?records.slice(0,4).map(render).join('')+(records.length>4?`<details><summary>其余 ${records.length-4} 条原始记录</summary>${records.slice(4,40).map(render).join('')+(records.length>40?'<small>预览前 40 条；对照及 CSV 保留全部 '+records.length+' 条记录。</small>':'')}</details>`:''):'<span class="material-no-records">尚无性能记录</span>';
 }
 function results(){const rows=filterMaterials(all(),state.filters);return showSelected?rows.filter(row=>state.keys.includes(row.key)):rows;}
 function renderRows(){const host=$('#material-picker-results');if(!host)return;const focusKey=document.activeElement?.dataset.materialChoice;const rows=results(),r=resolved(),keys=new Set(state.keys);host.innerHTML=rows.slice(0,limit).map((row,index)=>`<article class="material-choice ${keys.has(row.key)?'is-selected':''}" data-material-row="${esc(row.key)}"><label class="material-choice-check" for="material-choice-${index}"><input id="material-choice-${index}" type="checkbox" data-material-choice="${esc(row.key)}" ${keys.has(row.key)?'checked':''} aria-label="选择 ${esc(row.materialName)}，${esc(row.sample||'样品未填')}，${esc(row.conditions||'条件未填')}，成分 ${esc(row.composition||'未填写')}，材料记录 ${esc(row.materialId)}，来源 ${esc(row.paper.title)}"></label><div class="material-choice-content"><label class="material-name" for="material-choice-${index}">${esc(row.materialName)}</label>${row.composition?`<p class="material-composition">${esc(row.composition)}</p>`:''}<div class="material-context"><span>样品：${esc(row.sample||'未填写')}</span><span>条件：${esc(row.conditions||'未填写')}</span></div><div class="material-source"><span>来源文献</span><button type="button" data-material-open-paper="${esc(row.paperId)}" title="打开完整文献信息">${esc(row.paper.title)}</button><small>${esc([row.paper.year,row.paper.journal].filter(Boolean).join(' · '))}</small></div><div class="material-parameters">${recordHTML(row)}</div></div></article>`).join('')||'<div class="notes-empty">没有匹配的材料 / 样品。可清除名称、参数或来源筛选；已有选择继续保留。</div>';
  $('#material-result-count').textContent=`${rows.length} 项匹配${rows.length>limit?` · 当前显示 ${limit} 项`:''}`;$('#material-more').hidden=rows.length<=limit;$('#material-select-all').textContent=`全选当前 ${rows.length} 项结果`;$('#material-select-all').disabled=!rows.length;
  $('#material-picker-count').textContent=`已选 ${r.selected.length} 项材料 / 样品（${r.materials} 个材料，${r.papers} 篇来源）${r.selected.some(row=>!rows.some(item=>item.key===row.key))?' · 含当前筛选之外的选择':''}`;
  if(focusKey)[...host.querySelectorAll('[data-material-choice]')].find(input=>input.dataset.materialChoice===focusKey)?.focus({preventScroll:true});$('#material-picker-missing').innerHTML=missingHTML(r);document.querySelectorAll('[data-material-done]').forEach(button=>button.disabled=!r.selected.length);status();
 }
 function open(preferredParameter=null,requestedTab='table'){
  if(!supported()){config.toast('请重启 Materia，以启用按材料选择。');return;}
  nextTab=requestedTab;preferred=preferredParameter||preferred;const next={...state,mode:'material',filters:{...state.filters}};
  if(preferredParameter){next.filters.parameter=parameterNameKey(preferredParameter.name);next.filters.unit=preferredParameter.unit??'*';next.filters.query='';next.filters.paperId='';showSelected=false;}
  if(JSON.stringify(next)!==JSON.stringify(state))change(next);limit=100;show();
 }
 function show(){
  const rows=all(),inventory=materialParameterInventory(rows),parameter=inventory.find(p=>p.key===state.filters.parameter),papers=[...new Map(rows.map(row=>[row.paperId,row.paper])).values()].sort((a,b)=>a.title.localeCompare(b.title));
  config.showModal('直接选择材料与样品','来自同篇或跨文献的材料可独立勾选；名称、来源与测试条件分别呈现。',`${modeBar()}<section id="material-picker"><div class="material-picker-filters"><label>材料名称 / 成分<input id="material-query" type="search" maxlength="1000" value="${esc(state.filters.query)}" placeholder="名称、成分、样品或条件…"></label><label>性能参数<select id="material-parameter"><option value="">全部已录入材料</option>${inventory.map(p=>`<option value="${esc(p.key)}" ${p.key===state.filters.parameter?'selected':''}>${esc(p.name)} · ${p.count} 项</option>`).join('')}${state.filters.parameter&&!parameter?`<option value="${esc(state.filters.parameter)}" selected>原参数已无记录：${esc(state.filters.parameter)}</option>`:''}</select></label><label>参数单位<select id="material-unit" ${!parameter?'disabled':''}><option value="*">全部单位</option>${(parameter?.units||[]).map(unit=>`<option value="${esc(unit)}" ${unit===state.filters.unit?'selected':''}>${esc(unit||'单位未填')}</option>`).join('')}${state.filters.unit!=='*'&&!parameter?.units.includes(state.filters.unit)?`<option value="${esc(state.filters.unit)}" selected>原单位已无记录：${esc(state.filters.unit||'未填写')}</option>`:''}</select></label><label>来源文献<select id="material-source"><option value="">全部来源</option>${papers.map(p=>`<option value="${esc(p.id)}" ${p.id===state.filters.paperId?'selected':''}>${esc(p.title)}</option>`).join('')}${state.filters.paperId&&!papers.some(p=>p.id===state.filters.paperId)?`<option value="${esc(state.filters.paperId)}" selected>原来源已无可选材料（${esc(state.filters.paperId)}）</option>`:''}</select></label></div><p class="material-finder-note">按已录入的参数名称查找，空白或无效数值仍会列出。绘图时会明确列出单位、缺失坐标或配对条件不一致的原因。</p><div class="material-picker-toolbar"><span id="material-result-count"></span><button class="text-button" id="material-select-all" data-material-action="select-results"></button><button class="text-button" data-material-action="clear">清空材料选择</button><button class="text-button" data-material-action="reset-filters">清除筛选</button><label><input id="material-show-selected" type="checkbox" ${showSelected?'checked':''}>只看已选</label></div><div id="material-picker-missing"></div><div id="material-picker-results"></div><button id="material-more" class="text-button" data-material-action="more" hidden>继续显示匹配材料</button><div class="material-picker-footer"><strong id="material-picker-count"></strong><button class="outline-button" data-material-done="table">参数对照</button><button class="primary" data-material-done="chart">科研绘图</button></div></section>`,'comparison');renderRows();
 }
 function updateFilters(values,delay=false){if(change({...state,filters:{...state.filters,...values}},{delay})){limit=100;renderRows();}}
 document.addEventListener('input',event=>{if(event.target.id==='material-query'){const value=event.target.value;clearTimeout(inputTimer);inputTimer=setTimeout(()=>updateFilters({query:value},true),100);}});
 document.addEventListener('change',event=>{const e=event.target;if(e.dataset.materialChoice){const keys=new Set(state.keys);e.checked?keys.add(e.dataset.materialChoice):keys.delete(e.dataset.materialChoice);if(change({...state,keys:[...keys]}))renderRows();return;}if(e.id==='material-parameter'){updateFilters({parameter:e.value,unit:'*'});show();}if(e.id==='material-unit')updateFilters({unit:e.value});if(e.id==='material-source')updateFilters({paperId:e.value});if(e.id==='material-show-selected'){showSelected=e.checked;renderRows();}});
 document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.materialMode){const mode=button.dataset.materialMode;if(await setMode(mode))mode==='material'?open(null,nextTab):config.onPaper();return;}
  if(button.dataset.materialParameter){open({name:button.dataset.materialParameter,unit:button.dataset.materialParameterUnit||'*'},'chart');return;}
  if(button.dataset.materialDone){await flush();config.onDone(button.dataset.materialDone,state.filters.parameter?{name:state.filters.parameter,unit:state.filters.unit}:null);return;}
  if(button.dataset.materialOpenPaper){await flush();config.openPaper(button.dataset.materialOpenPaper);return;}
  if(button.dataset.materialRemove&&button.closest('.material-selected-list')){if(change({...state,keys:state.keys.filter(key=>key!==button.dataset.materialRemove)}))config.onDone(nextTab);return;}
  if(button.matches('[data-material-retry]')){await flush();return;}if(button.matches('[data-material-discard]')){if(saving)await saving.catch(()=>{});state=cleanMaterialSelection(saved);revision=savedRevision;error='';config.changed?.();state.mode==='paper'?config.onPaper():$('#material-picker')?show():config.onDone(nextTab);return;}
  const action=button.dataset.materialAction;if(action==='pick')open(null,nextTab);if(action==='more'){limit+=100;renderRows();}if(action==='select-results'){change({...state,keys:[...new Set([...state.keys,...results().map(row=>row.key)])]});renderRows();}if(action==='clear'){change({...state,keys:[]});renderRows();}if(action==='reset-filters'){change({...state,filters:{query:'',parameter:'',unit:'*',paperId:''}});show();}if(action==='remove-missing'){const valid=new Set(resolved().selected.map(row=>row.key));change({...state,keys:state.keys.filter(key=>valid.has(key))});$('#material-picker')?renderRows():config.onDone(nextTab);}
 }catch(e){error=e.message;status();config.toast(e.message,true);}});
 return{open,flush,load,mode:()=>state.mode,modeBar,subjects,resolved,selectionHTML,status,setMode,workspace:tab=>{nextTab=tab;},audit:data=>materialSelectionAudit(config.getPapers(),state.keys,data),getState:()=>cleanMaterialSelection(state)};
}
